    /** Returns the number of customers matching {@code filter}. */
    public int count(CustomerFilter filter) {
        int total = (int) customers.stream().filter(customer -> matches(customer, filter)).count();
        queryLog.recordCount(total);
        return total;
    }

    private static boolean matches(Customer customer, CustomerFilter filter) {
        if (!filter.statuses().isEmpty() && !filter.statuses().contains(customer.status())) {
            return false;
        }
        List<String> terms = nameTerms(filter.name());
        if (terms.isEmpty()) {
            return true;
        }
        String firstName = fold(customer.firstName());
        String lastName = fold(customer.lastName());
        return terms.stream().allMatch(term -> firstName.contains(term) || lastName.contains(term));
    }

    private static List<String> nameTerms(String name) {
        if (name == null || name.isBlank()) {
            return List.of();
