/**
 * Lists customers in a lazily loaded {@link Grid}, filterable by name and
 * status.
 *
 * <p>The grid never holds the whole data set: it asks the backend for one page
 * at a time and asks separately for the total row count, both restricted to
 * whatever filter is currently active. The filter is reflected in the URL so a
 * narrowed view can be bookmarked or shared.
 */
@Route("")
@PageTitle("Customers")
public class CustomerListView extends VerticalLayout implements BeforeEnterObserver {

    private final CustomerService customerService;
    private final Grid<Customer> grid = new Grid<>(Customer.class, false);
    private final TextField nameFilter = new TextField();
    private final MultiSelectComboBox<CustomerStatus> statusFilter = new MultiSelectComboBox<>();
    private final Span summary = new Span();
    private final GridLazyDataView<Customer> dataView;

    private final int totalCustomers;
    private CustomerFilter currentFilter = CustomerFilter.EMPTY;
    private String routePath = "";

    public CustomerListView(CustomerService customerService) {
        this.customerService = customerService;
        this.totalCustomers = customerService.count(CustomerFilter.EMPTY);

        setSizeFull();
        add(new H2("Customers"), buildFilterBar(), summary, grid);

        dataView = configureGrid();
        updateSummary(totalCustomers);
    }

    private HorizontalLayout buildFilterBar() {
        nameFilter.setPlaceholder("Filter by name");
        nameFilter.setValueChangeMode(ValueChangeMode.LAZY);
        nameFilter.addValueChangeListener(e -> applyFilters());

        statusFilter.setLabel("Status");
        statusFilter.setItems(CustomerStatus.values());
        statusFilter.addValueChangeListener(e -> applyFilters());

        return new HorizontalLayout(nameFilter, statusFilter);
    }\

